const grid=document.querySelector('#grid'),filter=document.querySelector('#filter'),type=document.querySelector('#type');function render(){const q=filter.value.toLowerCase();const items=BINGE_CATALOG.filter(x=>(type.value==='all'||x.type===type.value)&&x.title.toLowerCase().includes(q));grid.innerHTML=items.map(x=>`<article class="catalog-card"><small>${x.type==='movies'?'SAGA':x.type.toUpperCase()} · ${x.year}</small><h2>${x.title}</h2><p>${x.total} ${x.type==='movies'?'películas':'episodios'} · ≈ ${Math.round(x.total*x.avg/60)} horas<br>${x.status}</p><a href="/?title=${x.id}">Calcular mi plan →</a></article>`).join('')||'<p>No hay resultados. Prueba el modo manual.</p>'}filter.addEventListener('input',render);type.addEventListener('change',render);render();
